Algoritmo Triangle
  Definir a Como Entero;
  Definir b Como Entero;
  Definir c Como Entero;
  Leer a;
  Leer b;
  Leer c;
  Si a >= b + c O b >= a + c O c >= a + b Entonces
    Escribir "not a triangle";
  Sino
    Si a = b Y b = c Entonces
      Escribir "equilateral";
    Sino
      Si a = b O b = c O a = c Entonces
        Escribir "isosceles";
      Sino
        Escribir "scalene";
      FinSi
    FinSi
  FinSi
FinAlgoritmo
